// Package pyunicodedata reproduces unicodedata.lookup of CPython 3.13.16
// (Unicode 15.1.0): the name of a character, of a name alias or of a named
// sequence, and the algorithmic names CPython generates.
package pyunicodedata

import (
	"bufio"
	"bytes"
	"compress/gzip"
	_ "embed"
	"fmt"
	"strconv"
	"strings"
	"sync"
)

// names.txt.gz is generated by TESTS/fixtures/generate_unicode_names.py: the
// name of every code point unicodedata.name returns (Hangul syllables
// included), the aliases and named sequences of the UCD files, and the
// PREFIX-HEX families CPython generates as ranges.
//
//go:embed names.txt.gz
var namesGz []byte

// maxNameLength is NAME_MAXLEN of CPython's unicodedata: a longer name is not
// found.
const maxNameLength = 256

// span is a contiguous range of code points of a PREFIX-HEX family.
type span struct {
	first, last rune
}

// family is an algorithmic family of names: prefix followed by four to six
// upper-case hex digits without a leading zero.
type family struct {
	prefix string
	spans  []span
}

var (
	loadOnce sync.Once
	nameMap  map[string]string
	families []family
	loadErr  error
)

func load() {
	loadOnce.Do(func() {
		nameMap, families, loadErr = parseNames(namesGz)
	})
	if loadErr != nil {
		panic(loadErr)
	}
}

// parseNames reads the embedded data file.
func parseNames(data []byte) (map[string]string, []family, error) {
	reader, err := gzip.NewReader(bytes.NewReader(data))
	if err != nil {
		return nil, nil, fmt.Errorf("pyunicodedata: open names: %w", err)
	}
	defer reader.Close()
	scanner := bufio.NewScanner(reader)
	if !scanner.Scan() {
		return nil, nil, fmt.Errorf("pyunicodedata: names: %v", scanner.Err())
	}
	if scanner.Text() != "# pyunicodedata 15.1.0" {
		return nil, nil, fmt.Errorf("pyunicodedata: names: unknown header %q", scanner.Text())
	}
	names := map[string]string{}
	byPrefix := map[string]*family{}
	var order []*family
	for line := 2; scanner.Scan(); line++ {
		fields := strings.Split(scanner.Text(), "\t")
		switch {
		case fields[0] == "A" && len(fields) == 4:
			first, err := strconv.ParseUint(fields[2], 16, 32)
			if err != nil {
				return nil, nil, fmt.Errorf("pyunicodedata: names line %d: %w", line, err)
			}
			last, err := strconv.ParseUint(fields[3], 16, 32)
			if err != nil {
				return nil, nil, fmt.Errorf("pyunicodedata: names line %d: %w", line, err)
			}
			fam, ok := byPrefix[fields[1]]
			if !ok {
				fam = &family{prefix: fields[1]}
				byPrefix[fields[1]] = fam
				order = append(order, fam)
			}
			fam.spans = append(fam.spans, span{first: rune(first), last: rune(last)})
		case fields[0] == "N" && len(fields) == 3:
			value, err := hexValue(fields[2])
			if err != nil {
				return nil, nil, fmt.Errorf("pyunicodedata: names line %d: %w", line, err)
			}
			names[fields[1]] = value
		default:
			return nil, nil, fmt.Errorf("pyunicodedata: names line %d: %q", line, scanner.Text())
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, nil, fmt.Errorf("pyunicodedata: names: %w", err)
	}
	all := make([]family, 0, len(order))
	for _, fam := range order {
		all = append(all, *fam)
	}
	return names, all, nil
}

// hexValue decodes the space-separated hex code points of a value: one
// character for a name or an alias, several for a named sequence.
func hexValue(field string) (string, error) {
	var out strings.Builder
	for _, part := range strings.Fields(field) {
		code, err := strconv.ParseUint(part, 16, 32)
		if err != nil {
			return "", err
		}
		if code > 0x10FFFF {
			return "", fmt.Errorf("code point %s", part)
		}
		out.WriteRune(rune(code))
	}
	return out.String(), nil
}

// Lookup is unicodedata.lookup(name): the character a Unicode name stands for
// (case-insensitive, for name aliases, named sequences and the algorithmic
// PREFIX-HEX names), or false when CPython raises KeyError.
func Lookup(name string) (string, bool) {
	load()
	if len(name) > maxNameLength {
		return "", false
	}
	for _, fam := range families {
		if !hasPrefixFold(name, fam.prefix) {
			continue
		}
		code, ok := hexSpan(name[len(fam.prefix):], fam.spans)
		if !ok {
			return "", false
		}
		return string(code), true
	}
	value, ok := nameMap[asciiUpper(name)]
	return value, ok
}

// hasPrefixFold compares the first bytes of name with an upper-case ASCII
// prefix, ignoring the case of ASCII letters (PyOS_strnicmp).
func hasPrefixFold(name, prefix string) bool {
	if len(name) < len(prefix) {
		return false
	}
	for i := 0; i < len(prefix); i++ {
		if asciiUpperByte(name[i]) != asciiUpperByte(prefix[i]) {
			return false
		}
	}
	return true
}

// hexSpan parses parse_hex_code of CPython: four to six hex digits without a
// leading zero, a value in one of the spans.
func hexSpan(suffix string, spans []span) (rune, bool) {
	if len(suffix) < 4 || len(suffix) > 6 || suffix[0] == '0' {
		return 0, false
	}
	var value rune
	for i := 0; i < len(suffix); i++ {
		digit := asciiUpperByte(suffix[i])
		switch {
		case digit >= '0' && digit <= '9':
			value = value*16 + rune(digit-'0')
		case digit >= 'A' && digit <= 'F':
			value = value*16 + rune(digit-'A') + 10
		default:
			return 0, false
		}
	}
	if value > 0x10FFFF {
		return 0, false
	}
	for _, s := range spans {
		if value >= s.first && value <= s.last {
			return value, true
		}
	}
	return 0, false
}

// asciiUpperByte is Py_TOUPPER: only the ASCII letters change.
func asciiUpperByte(c byte) byte {
	if c >= 'a' && c <= 'z' {
		return c - ('a' - 'A')
	}
	return c
}

// asciiUpper upper-cases the ASCII letters of a name, as the name lookup of
// CPython compares the bytes (non-ASCII bytes stay as they are).
func asciiUpper(name string) string {
	for i := 0; i < len(name); i++ {
		if name[i] >= 'a' && name[i] <= 'z' {
			upper := []byte(name)
			for j := i; j < len(upper); j++ {
				upper[j] = asciiUpperByte(upper[j])
			}
			return string(upper)
		}
	}
	return name
}
